# g(w) = max #E8 lines whose label (1,cls) lies in a w-dim subspace of F2^9  == max #root classes in an affine (w-1)-flat of F2^8.
# Enumerate linear k-subspaces L of F2^8 as kernels of rank-(8-k) functional sets; count classes per coset (= syndrome).
import itertools, numpy as np
from e8 import cls
X=np.array(cls)
bits=((X[:,None]>>np.arange(8))&1)       # 120x8
def subspaces_dual(m):
    # all m-dim subspaces of F2^8 (as m x 8 RREF matrices), generated by pivot pattern
    for piv in itertools.combinations(range(8),m):
        free=[(i,c) for i in range(m) for c in range(8) if c not in piv and c>piv[i]]
        for b in itertools.product((0,1),repeat=len(free)):
            M=np.zeros((m,8),dtype=np.int64)
            for i,p in enumerate(piv): M[i,p]=1
            for (i,c),v in zip(free,b): M[i,c]=v
            yield M
g={}
for w in range(1,9):
    k=w-1; m=8-k
    if m==0: g[w]=120; continue
    best=0; nsub=0
    for M in subspaces_dual(m):
        nsub+=1
        syn=(bits@M.T)%2 @ (1<<np.arange(m))
        best=max(best,np.bincount(syn).max())
    g[w]=int(best); print('w=%d affine dim %d: #subspaces %d  g=%d'%(w,k,nsub,best),flush=True)
print(g)
